// Non-duplicating content picker.
// The sequence is derived from the DATE (advances one step every 2 days) so it needs no
// persisted state and never repeats: each step selects a DIFFERENT image and a UNIQUE
// hook+body caption combo. 6 imgs x 3 hooks x 3 bodies = 54 unique posts before any exact
// repeat (~108 days); consecutive posts never reuse the same image.
const DAY = 86400000;
const seq = Math.floor(Math.floor(Date.now() / DAY) / 2);

const LINK = 'https://play.google.com/store/apps/details?id=com.bedrockproxy';
const R2 = 'https://social.bedrockbroadcaster.com/posts/';

const POSTS = [
  { img: 'scene-broadcast.png',
    hooks: ['Turn any Bedrock server into one your console can see. \uD83C\uDFAE', 'Your console + any Bedrock server. Connected. \uD83C\uDFAE', 'Broadcast Bedrock servers straight to your console. \uD83D\uDCE1'],
    bodies: ['PS4, PS5, Xbox, Switch & Windows \u2014 no PC middleman.', 'No port forwarding, no PC, no hassle.', 'Pick a server, hit connect, you are in.'] },
  { img: 'scene-live.png',
    hooks: ['From tap to in-game in seconds. \u26A1', 'One tap and your console is on the server. \u26A1', 'No setup marathon \u2014 just connect and play. \u26A1'],
    bodies: ['Pick a server, hit connect, done.', 'Console gaming without the faff.', 'It really is that quick.'] },
  { img: 'scene-friends.png',
    hooks: ['Get the whole squad on one server. \uD83D\uDC7E', 'Console, mobile and PC \u2014 same world. \uD83D\uDC7E', 'Play with everyone, whatever they game on. \uD83D\uDC7E'],
    bodies: ['Cross-platform Bedrock, the easy way.', 'Nobody left out over hardware.', 'One server, all your friends.'] },
  { img: 'scene-saved.png',
    hooks: ['Save your servers, reconnect in one tap. \uD83D\uDD16', 'Your favourite servers, one tap away. \uD83D\uDD16', 'Never re-type a server IP again. \uD83D\uDD16'],
    bodies: ['No re-typing IPs every session.', 'Jump back in instantly.', 'Your server list, ready when you are.'] },
  { img: 'scene-packs.png',
    hooks: ['Bring your own resource packs \u2014 free. \u2728', 'Resource packs on console. No paywall. \u2728', 'Your packs, your console, zero cost. \u2728'],
    bodies: ['Servers push their packs straight to your console.', 'Free, automatic, no store.', 'The look you want, no extra charge.'] },
  { img: 'brand-square.png',
    hooks: ['Play Bedrock on your console, the easy way. \uD83C\uDFAE', 'Console Bedrock without the headaches. \uD83C\uDFAE', 'The simplest way onto Bedrock servers. \uD83C\uDFAE'],
    bodies: ['Switch support. Free packs. Close the app once you join.', 'PS, Xbox, Switch & Windows all welcome.', 'Set it up once, play whenever.'] }
];

const BROAD    = ['#minecraft','#minecraftbedrock','#gaming','#minecraftcommunity','#bedrock'];
const MID      = ['#bedrockserver','#minecraftconsole','#minecraftserver','#bedrockedition','#minecraftbedrockedition','#mcpe','#minecraftmultiplayer'];
const PLATFORM = ['#ps4minecraft','#ps5minecraft','#xboxminecraft','#switchminecraft','#minecraftswitch','#minecraftxbox','#minecraftps5','#consolegaming'];
const BRAND    = ['#bedrockbroadcaster','#playbedrock','#minecraftservers'];
function rotate(arr, n, count){ const out=[]; for(let i=0;i<count && i<arr.length;i++){ out.push(arr[((n+i)%arr.length+arr.length)%arr.length]); } return out; }

const N = POSTS.length, H = 3, B = 3, TOTAL = N * H * B;
const step = ((seq % TOTAL) + TOTAL) % TOTAL;
const imgIdx  = step % N;                 // image changes every single post
const combo   = Math.floor(step / N);     // 0..(H*B-1)
const hookIdx = combo % H;
const bodyIdx = Math.floor(combo / H) % B;

const post = POSTS[imgIdx];
const hook = post.hooks[hookIdx];
const body = post.bodies[bodyIdx];
const image_url = R2 + post.img;

const igTags = [...new Set([...BRAND, ...rotate(BROAD, seq, 4), ...rotate(MID, seq, 5), ...rotate(PLATFORM, seq, 6)])].slice(0, 28);
const fbTags = [...new Set([BRAND[0], ...rotate(BROAD, seq, 2)])];
const ig_caption = hook + '\n\n' + body + '\n\n\uD83D\uDC49 Get it free: ' + LINK + '\n\n' + igTags.join(' ');
const fb_caption = hook + '\n\n' + body + '\n\n\uD83D\uDC49 Get it free: ' + LINK + '\n\n' + fbTags.join(' ');

return [{ json: { seq, imgIdx, combo, image_url, angle: hook, ig_caption, fb_caption } }];

// Publishes to Instagram (2-step create -> poll -> publish) and Facebook (best-effort).
const helpers = this.helpers;
const token = $env.META_PAGE_TOKEN;
const IG = $env.IG_ACCOUNT_ID;
const FB = $env.FB_PAGE_ID;
const { image_url, ig_caption, fb_caption, angle, seq } = $input.first().json;
const G = 'https://graph.facebook.com/v23.0';
const req = (method, path, params) => helpers.httpRequest({ method, url: `${G}/${path}`, qs: params, json: true });
const errmsg = (e) => { const b = e.response && (e.response.body || e.response.data); if (b && b.error) return JSON.stringify(b.error); if (b) return (typeof b === 'string' ? b : JSON.stringify(b)).slice(0, 300); return (e && e.message) ? e.message : String(e); };
if (!token || !IG) throw new Error('Missing META_PAGE_TOKEN or IG_ACCOUNT_ID in env (restart pod after secret update).');
const result = { seq, angle, image_url, ig: {}, fb: {} };
try {
  const c = await req('POST', `${IG}/media`, { image_url, caption: ig_caption, access_token: token });
  const creationId = c.id; let status = 'IN_PROGRESS';
  for (let i = 0; i < 12 && status !== 'FINISHED'; i++) { await new Promise(r => setTimeout(r, 5000)); const s = await req('GET', creationId, { fields: 'status_code', access_token: token }); status = s.status_code; if (status === 'ERROR') throw new Error('IG container processing ERROR'); }
  if (status !== 'FINISHED') throw new Error('IG container not ready (last status: ' + status + ')');
  const p = await req('POST', `${IG}/media_publish`, { creation_id: creationId, access_token: token });
  result.ig = { ok: true, id: p.id };
  try { const pl = await req('GET', p.id, { fields: 'permalink', access_token: token }); result.ig.permalink = pl.permalink; } catch (_) {}
} catch (e) { result.ig = { ok: false, error: errmsg(e) }; }
try {
  const f = await req('POST', `${FB}/photos`, { url: image_url, caption: fb_caption, access_token: token });
  result.fb = { ok: true, id: f.id || f.post_id };
} catch (e) { result.fb = { ok: false, error: errmsg(e) }; }
return [{ json: result }];
